class CrossAndRedStreakAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_previous_sma = None
        self.aapl_red_streak = 0
        self.aapl_previous_close = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}
        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        if any(symbol not in data.Bars for symbol in symbols):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if self.aapl_previous_close is not None:
            if aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if not self.sma.IsReady or not self.rsi.IsReady:
            return

        if self.spy_previous_sma is None:
            self.spy_previous_sma = self.sma.Current.Value
            return

        spy_sma = self.sma.Current.Value
        aapl_rsi = self.rsi.Current.Value

        strategy_a_sold = False
        strategy_b_sold = False

        if self.strategy_a_lot > 0 and self.spy_previous_sma >= 0:
            if spy_close < spy_sma and self.spy_previous_close >= self.spy_previous_sma:
                if self._submit_sell("A", self.spy, self.strategy_a_lot):
                    strategy_a_sold = True

        if self.strategy_b_lot > 0 and aapl_rsi > 60:
            if self._submit_sell("B", self.aapl, self.strategy_b_lot):
                strategy_b_sold = True

        if (
            not strategy_a_sold
            and self.strategy_a_lot == 0
            and self.spy not in self.pending_orders.values()
            and spy_close > spy_sma
            and self.spy_previous_close <= self.spy_previous_sma
        ):
            shares = math.floor((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
            if shares > 0:
                self._submit_buy("A", self.spy, shares)

        if (
            not strategy_b_sold
            and self.strategy_b_lot == 0
            and self.aapl not in self.pending_orders.values()
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        ):
            shares = math.floor(20000 / aapl_close)
            if shares > 0:
                self._submit_buy("B", self.aapl, shares)

        self.spy_previous_close = spy_close
        self.spy_previous_sma = spy_sma

    def _submit_buy(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, tag=f"{strategy}_BUY")
        self.pending_orders[ticket.OrderId] = symbol

    def _submit_sell(self, strategy, symbol, quantity):
        if quantity <= 0:
            return False

        ticket = self.MarketOrder(symbol, -quantity, tag=f"{strategy}_SELL")
        self.pending_orders[ticket.OrderId] = symbol
        return True

    def OnOrderEvent(self, orderEvent):
        order_id = orderEvent.OrderId

        if order_id not in self.pending_orders:
            return

        symbol = self.pending_orders[order_id]
        fill_quantity = orderEvent.FillQuantity
        order = self.Transactions.GetOrderById(order_id)

        if order is not None:
            if order.Tag == "A_BUY":
                self.strategy_a_lot += fill_quantity
            elif order.Tag == "A_SELL":
                self.strategy_a_lot += fill_quantity
            elif order.Tag == "B_BUY":
                self.strategy_b_lot += fill_quantity
            elif order.Tag == "B_SELL":
                self.strategy_b_lot += fill_quantity

        if orderEvent.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        ]:
            if orderEvent.Status != OrderStatus.PartiallyFilled:
                del self.pending_orders[order_id]
