from AlgorithmImports import *
from collections import deque
from math import floor


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.closes = {
            ticker: deque(maxlen=101)
            for ticker in self.symbols
        }

        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.RegisterIndicator(
            self.symbols["AAPL"],
            self.rsi,
            Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_red_streak = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        present = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            if bar is None or bar.Close <= 0:
                continue

            present[ticker] = bar

        for ticker, bar in present.items():
            history = self.closes[ticker]

            if history:
                if bar.Close < history[-1]:
                    if ticker == "AAPL":
                        self.aapl_red_streak += 1
                elif ticker == "AAPL":
                    self.aapl_red_streak = 0

            history.append(float(bar.Close))

        if len(present) != len(self.symbols):
            return

        if self.IsWarmingUp:
            return

        spy_closes = self.closes["SPY"]
        aapl_closes = self.closes["AAPL"]

        spy_cross_above = False
        spy_cross_below = False

        if len(spy_closes) >= 101:
            spy_previous_close = spy_closes[-2]
            spy_current_close = spy_closes[-1]

            spy_previous_sma = sum(list(spy_closes)[-101:-1]) / 100.0
            spy_current_sma = sum(list(spy_closes)[-100:]) / 100.0

            spy_cross_above = (
                spy_previous_close <= spy_previous_sma and
                spy_current_close > spy_current_sma
            )

            spy_cross_below = (
                spy_previous_close >= spy_previous_sma and
                spy_current_close < spy_current_sma
            )

        # Evaluate sells before buys.
        if self.spy_lot > 0 and spy_cross_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.rsi.IsReady and self.rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        # Strategy A buy.
        if self.spy_lot == 0 and spy_cross_above and len(spy_closes) >= 101:
            price = float(present["SPY"].Close)
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = floor(target_value / price)

            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        # Strategy B buy.
        if (
            self.aapl_lot == 0 and
            self.aapl_red_streak >= 3 and
            len(aapl_closes) >= 4
        ):
            price = float(present["AAPL"].Close)

            if self.Portfolio.Cash >= 20000:
                quantity = floor(20000 / price)

                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity
